PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS stores(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,domain TEXT,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS brands(id TEXT PRIMARY KEY,store_id TEXT NOT NULL,name TEXT NOT NULL,slug TEXT NOT NULL,UNIQUE(store_id,slug),FOREIGN KEY(store_id) REFERENCES stores(id));
CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY,store_id TEXT NOT NULL,name TEXT NOT NULL,slug TEXT NOT NULL,UNIQUE(store_id,slug),FOREIGN KEY(store_id) REFERENCES stores(id));
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,store_id TEXT NOT NULL,brand_id TEXT,category_id TEXT,name TEXT NOT NULL,slug TEXT NOT NULL,description TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','active','archived')),price INTEGER NOT NULL DEFAULT 0,sale_price INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(store_id,slug),FOREIGN KEY(store_id) REFERENCES stores(id));
CREATE TABLE IF NOT EXISTS product_images(id TEXT PRIMARY KEY,store_id TEXT NOT NULL,product_id TEXT NOT NULL,url TEXT NOT NULL,alt TEXT DEFAULT '',sort_order INTEGER DEFAULT 0,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS variants(id TEXT PRIMARY KEY,store_id TEXT NOT NULL,product_id TEXT NOT NULL,sku TEXT NOT NULL,size TEXT,color TEXT,price INTEGER,sale_price INTEGER,status TEXT NOT NULL DEFAULT 'active',UNIQUE(store_id,sku),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS inventory_locations(id TEXT PRIMARY KEY,store_id TEXT NOT NULL,name TEXT NOT NULL,code TEXT NOT NULL,UNIQUE(store_id,code));
CREATE TABLE IF NOT EXISTS inventory_levels(store_id TEXT NOT NULL,location_id TEXT NOT NULL,variant_id TEXT NOT NULL,on_hand INTEGER NOT NULL DEFAULT 0,reserved INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(location_id,variant_id),CHECK(on_hand>=0),CHECK(reserved>=0),CHECK(reserved<=on_hand));
CREATE TABLE IF NOT EXISTS inventory_movements(id TEXT PRIMARY KEY,store_id TEXT NOT NULL,location_id TEXT NOT NULL,variant_id TEXT NOT NULL,type TEXT NOT NULL,qty INTEGER NOT NULL,reference_type TEXT,reference_id TEXT,note TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY,store_id TEXT NOT NULL,name TEXT NOT NULL,phone TEXT,email TEXT,address TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,store_id TEXT NOT NULL,order_no TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new' CHECK(status IN('new','confirmed','packing','shipping','completed','cancelled','returned')),customer_id TEXT,subtotal INTEGER NOT NULL DEFAULT 0,discount INTEGER NOT NULL DEFAULT 0,total INTEGER NOT NULL DEFAULT 0,note TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(store_id,order_no));
CREATE TABLE IF NOT EXISTS order_items(id TEXT PRIMARY KEY,store_id TEXT NOT NULL,order_id TEXT NOT NULL,variant_id TEXT NOT NULL,sku TEXT NOT NULL,name TEXT NOT NULL,qty INTEGER NOT NULL CHECK(qty>0),unit_price INTEGER NOT NULL,line_total INTEGER NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS order_status_history(id TEXT PRIMARY KEY,store_id TEXT NOT NULL,order_id TEXT NOT NULL,from_status TEXT,to_status TEXT NOT NULL,note TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS promotions(id TEXT PRIMARY KEY,store_id TEXT NOT NULL,code TEXT,name TEXT NOT NULL,type TEXT NOT NULL,value INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,starts_at TEXT,ends_at TEXT);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY,store_id TEXT NOT NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,payload TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_products_store_status ON products(store_id,status);
CREATE INDEX IF NOT EXISTS idx_variants_store_sku ON variants(store_id,sku);
CREATE INDEX IF NOT EXISTS idx_orders_store_status_created ON orders(store_id,status,created_at);
CREATE INDEX IF NOT EXISTS idx_inventory_store_variant ON inventory_levels(store_id,variant_id);
CREATE INDEX IF NOT EXISTS idx_movements_store_created ON inventory_movements(store_id,created_at);
